'use strict';
const D=window.TERROR;
const navGroups=[
 {title:'Mit dem Stück beginnen',items:[['lektuere','Text & Szenenfilm'],['film','Filmvisionierung & Werkstatt']]},
 {title:'Bei Bedarf beiziehen',items:[['grundlagen','Begriffe & Grundkurs'],['rollen','Rollenlabor'],['befehlskette','Befehlskette'],['geschichte','Verfassung & Geschichte'],['recht','Recht & Urteil'],['philosophie','Denkpositionen'],['dilemma','Dilemma-Labor'],['aviatik','Aviatik & Lagebild'],['flydubai','Fallakte Flydubai'],['politik','Politik & Weltbilder']]},
 {title:'Erproben & festhalten',items:[['simulation','Verhandlung'],['spiele','Lernspiele'],['start','Arbeitsraum'],['journal','Mein Journal'],['quellen','Quellen']]}
];
const navs=navGroups.flatMap(group=>group.items);
const KEY='terror-learning-v1';
let state={notes:{},done:[],answers:{},sim:{stage:0,answers:{}},clips:[],votes:{},prefs:{}},storageOK=true,pdfURL='',currentVideo=null,clipEnd=null,filmObjectURL='';
try{const saved=JSON.parse(localStorage.getItem(KEY)||'null');if(saved&&saved.notes&&saved.sim)state={...state,...saved};}catch(e){storageOK=false;}
const main=document.getElementById('main');
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const external=(url,label)=>`<a href="${escape(url)}" target="_blank" rel="noopener noreferrer">${escape(label)} ↗</a>`;
const list=items=>`<ol>${items.map(x=>`<li>${x}</li>`).join('')}</ol>`;
const note=(id,label,help='')=>`<label class="field"><span>${escape(label)}</span>${help?`<span class="help">${escape(help)}</span>`:''}<textarea data-note="${escape(id)}" data-label="${escape(label)}" placeholder="Deine Beobachtung, dein Beleg, deine Deutung …">${escape(state.notes[id]?.text||'')}</textarea></label>`;
const source=id=>id==='studie'?'<p class="source">Didaktischer Bezug: Hans-Joachim Roth (2022), S. 125–140, in der bereitgestellten Datei 4555Volltext.pdf. <a href="#quellen">Bibliografie</a></p>':D.sources[id]?`<p class="source">Quelle: ${external(D.sources[id].url,D.sources[id].title)}</p>`:'';
const details=(title,content)=>`<details><summary>${title}</summary><div>${content}</div></details>`;
const head=(eyebrow,title,lead='')=>`${visualHeader()}<span class="eyebrow">${eyebrow}</span><h1>${title}</h1>${lead?`<p class="lead">${lead}</p>`:''}`;
const checklist=(id,labels)=>`<div class="checklist">${labels.map((x,i)=>`<label><input type="checkbox" data-check="${id}-${i}" ${state.answers[id+'-'+i]?'checked':''}>${x}</label>`).join('')}</div>`;
const rubric=id=>details('Deine Antwort prüfen',`<p>Bewerte die Begründung, nicht die gewählte Seite. Jede erfüllte Zeile braucht eine erkennbare Stelle in deinem Text.</p>${checklist('rubric-'+id,['Ich nenne eine präzise Beobachtung oder These.','Ich belege sie mit einer Textstelle oder Quelle.','Ich erkläre, wie der Beleg meine Deutung trägt.','Ich prüfe einen Gegenbeleg oder eine Grenze meiner Aussage.'])}<p>Fehlt ein Punkt? Überarbeite gezielt diesen Teil. Dieses Raster ergänzt das Sprachfeedback. Eine automatische Note für freie Texte wird nicht vergeben.</p>`);
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));storageOK=true;}catch(e){storageOK=false;}updateProgress();}
function toast(s){const t=document.getElementById('toast');t.textContent=s;t.style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>t.style.display='none',3200);}
function updateProgress(){const n=state.done.length;document.getElementById('progress').innerHTML=`${n} von ${D.modules.length} Lektürestationen reflektiert<div class="progress-track"><i style="width:${n/D.modules.length*100}%"></i></div>`;document.getElementById('saveState').textContent=storageOK?'Journal auf diesem Gerät gespeichert':'Speichern nicht möglich – Journal bitte exportieren';}
function completion(id){return `<button class="${state.done.includes(id)?'secondary':'accent'}" data-complete="${id}" aria-pressed="${state.done.includes(id)}">${state.done.includes(id)?'Als reflektiert markiert':'Station als reflektiert markieren'}</button>`;}
function linkCard(href,n,title,text,meta=''){return `<a class="card card-link" href="#${href}">${filmCardImage(href)}<span class="number">${n}</span><h3>${title}</h3><p>${text}</p>${meta?`<span class="meta">${meta}</span>`:''}</a>`;}
function start(){return head('DEIN ARBEITSRAUM / OFFENE LEKTÜRE','Ein Fall. Viele Perspektiven.<br>Dein begründetes Urteil.','Ferdinand von Schirachs «Terror» macht das Publikum zum Gericht. Untersuche den Text, wechsle die Perspektive und prüfe deine Gründe.')+`<div class="workspace-grid"><section class="case-panel"><span class="eyebrow">AKTE 01 · DER FALL LARS KOCH</span><h2>Darf retten bedeuten,<br>Unschuldige zu töten?</h2><p>Ein entführtes Passagierflugzeug steuert auf ein vollbesetztes Stadion zu. Kampfpilot Lars Koch schiesst die Maschine gegen den Befehl ab. Jetzt steht er vor Gericht.</p><div class="case-numbers"><div><strong>164</strong><span>Menschen im Flugzeug</span></div><div><strong>70’000</strong><span>Menschen im Stadion bedroht</span></div></div><p>Deine erste Intuition – noch kein juristisches Urteil:</p><div class="choice-row">${['Eher verurteilen','Noch offen','Eher freisprechen'].map(v=>`<button class="secondary" data-vote="${v}" aria-pressed="${state.votes.initial===v}">${v}</button>`).join('')}</div><p class="intro-note" id="voteResult">${state.votes.initial?'Anfangsvotum: '+escape(state.votes.initial)+'. Du kannst deine Begründung später vergleichen.':'Du darfst die Entscheidung offenhalten. Wichtig ist, wie du sie begründest.'}</p></section><section class="card"><span class="eyebrow">DEIN NÄCHSTER SCHRITT</span><h2>Beginne mit Text oder Film.</h2><div class="route-list"><a href="#lektuere"><b>01</b><span>Ich möchte den Text verstehen.</span></a><a href="#film"><b>02</b><span>Ich möchte die Inszenierung lesen.</span></a><p class="muted">Danach oder bei einer offenen Frage:</p><a href="#rollen"><span>Ich möchte eine Figur erproben.</span></a><a href="#recht"><span>Ich möchte Recht und Moral trennen.</span></a></div>${note('anfang','Mein erster Grund','Was erscheint dir entscheidend? Welche Information fehlt dir?')}</section></div><section class="section"><div class="section-head"><h2>Deine Lernlandschaft</h2><span class="muted">Kein fester Zeitplan. Mehrere mögliche Wege.</span></div><div class="grid three">${linkCard('lektuere','01–12','Den Text erschliessen','Zwölf Stationen mit Textbelegen, Hilfen und Vergleichshorizonten.','Lektüre · Sprache · Dramenform')}${linkCard('rollen','7 ROLLEN','Eine fremde Position aushalten','Selbstbild, Wissen und blinde Flecken der Figuren untersuchen.','Rolleninterpretation · szenisches Lesen')}${linkCard('dilemma','6 FÄLLE','Die Bedingungen verändern','Prüfen, ob dein Argument auch unter veränderten Bedingungen trägt.','Gedankenexperimente · Modellkritik')}${linkCard('philosophie','8 POSITIONEN','Mit Begriffen genauer denken','Würde, Nutzen, Verantwortung, Geltung und Fürsorge vergleichen.','Philosophie · begründeter Transfer')}${linkCard('simulation','7 SCHRITTE','Eine Verhandlung durchlaufen','Aussagen prüfen und schliesslich ein eigenes Urteil begründen.','Selbstlern-Simulation · Gegenfragen')}${linkCard('politik','6 PERSPEKTIVEN','Den politischen Rahmen lesen','Sicherheit, Ausnahme, Mehrheit, Weltbilder und Medienkritik.','Gesellschaft · Kontroverse')}</div></section><section class="section grid"><div class="card"><h2>Flugkarten, Tower & Luftlage</h2><p>Erkunde acht aviatische Stationen: echte Karten und Fotos, ein interaktives Lagebild, Zeit-Distanz-Rechnungen und die Grenzen technischen Wissens.</p><p><a href="#aviatik">Die aviatische Einheit öffnen →</a></p><h2>Gemeinsam vor Gericht</h2><p>Verhandelt den Fall mit sechs Mitspieler*innen: feste Rollen, gemeinsamer Chat, Fallakten, vollständiges Grundgesetz und Entscheidungshilfe für den Vorsitz.</p><p><a href="spielraum/">Multiplayer-Spielraum öffnen →</a></p><h2>Drei Fragen auseinanderhalten</h2><p><b>Literarisch:</b> Wie lenken Text und Inszenierung mein Urteil?</p><p><b>Moralisch:</b> Welche Handlung halte ich aus welchen Gründen für richtig?</p><p><b>Rechtlich:</b> Welche Normen und Voraussetzungen sind zu prüfen?</p><a href="#recht">Die Unterschiede erarbeiten</a></div><div class="card"><h2>So arbeitest du selbstständig</h2>${list(['Lies die angegebene Stelle in deiner Ausgabe.','Schreibe zuerst eine eigene Antwort, öffne dann die Hilfe.','Vergleiche mit dem Erwartungshorizont und überarbeite.','Sichere einen Beleg und eine offene Frage im Journal.'])}<p class="notice muted">Deine Notizen und Markierungen bleiben in diesem Browser. Exportiere dein Journal für ein anderes Gerät oder eine Abgabe.</p></div></section>`;}
function reading(id){if(id){const m=D.modules.find(x=>x.id===id);if(!m)return missing();return sceneReading(m);}

const filter=state.prefs.filter||'Alle';return head('HIER BEGINNEN / TEXT & KURATIERTER SZENENFILM','Das Stück lesen. Den Film erschliessen.','Wähle eine Szene: Film, passende PDF-Seiten und Analyseaufträge liegen in einem gemeinsamen Leseraum. Entwickle deine Deutung Schritt für Schritt.')+`<section class="card entry-path"><h2>Dein Ausgangspunkt ist das Stück.</h2><p>Lies den Text oder schaue den Film abschnittweise. In jeder Station findest du die passende Szene, PDF-Seiten und Beobachtungsaufträge. Halte zuerst deine eigenen Fragen fest. Begriffe, Befehlskette, Geschichte und Denkpositionen ziehst du dann gezielt zur Klärung bei.</p><div class="choice-row"><a class="button" href="#lektuere/auftakt">Mit dem Auftakt beginnen →</a><a class="button secondary" href="#film">Filmvisionierung & Werkstatt →</a></div></section><div class="callout"><b>Vor der Arbeit:</b> Öffne eine Station: Die eingebundene PDF erscheint automatisch an der passenden Stelle. Die Szenenleiste steuert den Filmausschnitt und die Textstelle gemeinsam. Seitenverweise beziehen sich auf die bereitgestellte PDF mit 103 Seiten.</div><div class="pill-row" role="group" aria-label="Stationen filtern">${['Alle','Form & Sprache','Argumentation','Figuren & Wissen','Transfer'].map(f=>`<button class="${filter===f?'':'secondary'}" data-filter="${f}" aria-pressed="${filter===f}">${f}</button>`).join('')}</div><div class="grid three">${D.modules.filter(m=>filter==='Alle'||m.area===filter).map(m=>linkCard('lektuere/'+m.id,String(D.modules.indexOf(m)+1).padStart(2,'0'),m.title,m.goal,`PDF ${m.pages} · ${state.done.includes(m.id)?'✓ Reflektiert':m.area}`)).join('')}</div><section class="section card"><h2>Drei mögliche Lektürewege</h2><p><b>Text und Inszenierung:</b> Auftakt → Meiser → Dramenform → Filmwerkstatt.</p><p><b>Argumentation und Urteil:</b> Anklage → Evakuierung → beide Plädoyers → Urteile.</p><p><b>Figur und Verantwortung:</b> Lauterbach → Koch → Meiser → Rollenlabor → Verhandlung.</p><p class="muted">Die Zeitangaben sind Orientierungshilfen für einzelne Stationen, kein verbindlicher Stundenplan.</p></section>`;}
function roles(id){const r=D.roles.find(x=>x.id===id);if(!r)return head('ROLLENLABOR / PERSPEKTIVEN','Anders sprechen. Anders sehen.','Eine Rolle verstehen heisst, ihre Gründe ernst zu nehmen und ihre Grenzen zu erkennen. Du kannst alle Perspektiven allein nacheinander erproben.')+`<div class="callout">Die Gegenfragen und Antwortimpulse sind didaktisch formuliert. Sie sind keine Originalzitate und kein Gespräch mit einer KI-Figur.</div><div class="grid three">${D.roles.map((r,i)=>linkCard('rollen/'+r.id,String(i+1).padStart(2,'0'),r.name,r.function,r.principle)).join('')}</div>`;
return `<p class="breadcrumb"><a href="#rollen">Rollenlabor</a> / ${r.name}</p>`+head(r.function,r.name,'Leitwert: '+r.principle)+`<div class="grid"><section class="card"><h2>Deine Rollenakte</h2><h3>Wissenshorizont</h3><p>${r.knowledge}</p><h3>Innerer Konflikt</h3><p>${r.tension}</p><h3>Sprache und Auftreten</h3><p>${r.language}</p><p class="source">Textbezug: PDF-S. ${r.pages}. Profil und Deutungen: Lernredaktion.</p>${note('rolle-beleg-'+id,r.name+' · Textanker','Notiere einen Beleg, eine Deutung und einen Gegenbeleg.')}</section><section class="card"><span class="eyebrow">IN DER ROLLE</span><h2>Deine Stellungnahme</h2><p>${r.prompt}</p>${note('rolle-'+id,r.name+' · Stellungnahme','120–180 Wörter. Bleibe innerhalb des belegbaren Wissens deiner Rolle.')}<button data-reveal="roleChallenge" class="accent">Mit einer Gegenfrage konfrontieren</button><div id="roleChallenge" hidden><div class="callout"><b>Gegenfrage:</b> ${r.challenge}</div>${note('rolle-antwort-'+id,r.name+' · Antwort auf die Gegenfrage')}${details('Antwortimpuls vergleichen',r.response)}</div></section></div><section class="section card"><h2>Aus der Rolle heraustreten</h2><p><b>Möglicher blinder Fleck:</b> ${r.blind}</p>${note('rolle-reflexion-'+id,r.name+' · Rollenreflexion','Wo widerspricht die Rolle deiner eigenen Position? Welche Geste, Pause oder Betonung würdest du einsetzen und warum?')}${rubric('rolle-'+id)}<p><a href="#simulation">Die Perspektive in der Verhandlung prüfen</a></p></section>`;}
function philosophy(){return head('RECHTSPHILOSOPHIE / 8 DENKPOSITIONEN','Nicht nur was du denkst.<br>Sondern warum.','Die Positionen sind Werkzeuge zur Prüfung deiner Gründe. Keine Figur verkörpert eine philosophische Schule vollständig.')+`<section class="card section"><h2>Erst den Konflikt kennenlernen</h2><p>Ein Denkwerkzeug ist eine Frage, mit der du eine Entscheidung untersuchst. Beginne mit einem einfachen Beispiel und dem Video zur Weiche. Danach liest du hier, wer hinter den Namen steht.</p><a href="#dilemma/weiche">Weichensteller-Dilemma mit Video →</a></section><div class="grid philosophy-basics">${D.philosophies.map(p=>`<article class="card"><span class="eyebrow">${p.question}</span><h3>${p.name}</h3>${foundationPeople(p)}${details('Für die Vertiefung: Kerngedanke',p.idea)}${details('Am Fall prüfen',`<p>${p.application}</p><p><b>Starker Einwand:</b> ${p.objection}</p>`)}${details('Nicht verwechseln',p.trap)}${details('Dein Denkauftrag',`<p>${p.task}</p>${note('philo-'+p.id,p.name+' · Denkauftrag')}`)}${source(p.source)}</article>`).join('')}</div><section class="section card"><h2>Zwei Positionen im direkten Vergleich</h2><div class="grid"><label class="field"><span>Position A</span><select id="philoA">${D.philosophies.map(p=>`<option value="${p.id}">${p.name}</option>`).join('')}</select></label><label class="field"><span>Position B</span><select id="philoB">${D.philosophies.map((p,i)=>`<option value="${p.id}" ${i===1?'selected':''}>${p.name}</option>`).join('')}</select></label></div><div id="philoCompare"></div>${note('philo-vergleich','Mein philosophischer Vergleich','Gemeinsamkeit · Unterschied im Massstab · Einwand gegen A · Einwand gegen B · eigenes Urteil')}${rubric('philo')}</section>`;}
function comparePhilo(){const a=D.philosophies.find(p=>p.id===document.getElementById('philoA').value),b=D.philosophies.find(p=>p.id===document.getElementById('philoB').value);document.getElementById('philoCompare').innerHTML=a.id===b.id?'<div class="callout">Wähle zwei unterschiedliche Positionen.</div>':`<div class="grid"><div class="comparison"><h3>${a.name}</h3><p>${a.question}</p><b>Prüffrage:</b> ${a.objection}</div><div class="comparison"><h3>${b.name}</h3><p>${b.question}</p><b>Prüffrage:</b> ${b.objection}</div></div>`;}
function dilemma(id){const d=D.dilemmas.find(x=>x.id===id);if(!d)return head('DILEMMA-LABOR / VARIATIONEN','Ändere den Fall.<br>Prüfe deinen Grund.','Gedankenexperimente legen Voraussetzungen offen. Sie sind keine Simulation realer Opferzahlen und keine automatische Rechtsberatung.')+`${foundationTrolley()}<div class="grid three">${D.dilemmas.map((d,i)=>linkCard('dilemma/'+d.id,String(i+1).padStart(2,'0'),d.title,d.text,d.kind)).join('')}</div><section class="section card"><h2>Der Schleier des Nichtwissens</h2><p>Formuliere eine allgemeine Regel, bevor du deine Position erfährst. Diese Übung ist eine didaktische Übertragung von Rawls’ Fairnessgedanken.</p>${note('schleier-regel','Meine Regel vor der Rollenzuteilung')}<button data-rawls class="accent">Eine Perspektive ziehen</button><div id="rawlsResult" class="callout" ${state.prefs.rawls?'':'hidden'}>${escape(state.prefs.rawls||'')}</div>${note('schleier-reflexion','Meine Regel nach dem Perspektivwechsel','Bleibt die Regel akzeptabel, wenn du Flugpassagier, Stadionbesucherin oder Pilot bist? Prüfe alle drei Rollen.')}<p class="source">Die Rollen werden gleichwahrscheinlich gezogen. Das bildet keine reale Risikoverteilung ab.</p>${source('rawls')}</section>`;
return `<p class="breadcrumb"><a href="#dilemma">Dilemma-Labor</a> / ${d.title}</p>`+head(d.kind,d.title,d.focus)+`${id==='weiche'?foundationTrolley():''}<div class="workspace-grid"><section class="card"><h2>Die Versuchsanordnung</h2><p class="lead">${d.text}</p><div class="choice-row">${[d.a,d.b,'Ich halte die Entscheidung offen'].map((v,i)=>`<button class="secondary" data-dilemma="${id}" data-option="${i}" aria-pressed="${state.answers['dilemma-'+id]===i}">${v}</button>`).join('')}</div><div id="dilemmaFeedback" ${state.answers['dilemma-'+id]===undefined?'hidden':''} class="callout">${d.feedback}</div>${note('dilemma-'+id,d.title+' · Begründung','Nenne eine Regel, eine Annahme und einen Einwand. Es gibt hier keine Punktzahl für deine Entscheidung.')}${rubric('dilemma-'+id)}</section><aside class="card"><h2>Der Transfer-Test</h2>${list(['Was nimmt das Modell als sicher an?','Wer entscheidet über wen?','Wird jemand als Mittel eingesetzt?','Welche Handlungsmöglichkeiten fehlen?','Was ändert sich beim Übergang zu einer allgemeinen Regel?'])}${note('dilemma-transfer-'+id,d.title+' · Grenze des Vergleichs','Welche Ähnlichkeit mit «Terror» trägt, welcher Unterschied ist entscheidend?')}<a href="#philosophie">Die Denkpositionen heranziehen</a></aside></div>`;}
function law(){return head('RECHT & URTEIL / DEUTSCHER FALL','Verstehen ist nicht rechtfertigen.','«Terror» behandelt einen fiktiven Fall im deutschen Rechtsrahmen. Prüfe die Ebenen getrennt; eine moralische Intuition ist noch kein strafrechtliches Ergebnis.')+`<section class="card"><h2>Der Prüfungsweg</h2><div class="grid three"><div><span class="number">01 · TATBESTAND</span><h3>Was wurde getan?</h3><p>Welche gesetzlichen Merkmale sind erfüllt? Die Anklage nennt Mord in 164 Fällen. Tötung, Vorsatz und die rechtliche Einordnung sind auseinanderzuhalten.</p></div><div><span class="number">02 · RECHTSWIDRIGKEIT</span><h3>War die Handlung erlaubt?</h3><p>Ein Rechtfertigungsgrund würde das Unrecht der Tat ausschliessen. § 34 StGB verlangt mehrere Voraussetzungen; ein Zahlenvergleich genügt nicht.</p></div><div><span class="number">03 · SCHULD</span><h3>Ist sie persönlich vorwerfbar?</h3><p>Ein Entschuldigungsgrund kann die persönliche Schuld ausschliessen, obwohl die Tat rechtswidrig bleibt. Strafzumessung ist nochmals eine andere Frage.</p></div></div><div class="callout">Eine fehlende staatliche Abschussermächtigung und die individuelle Strafbarkeit eines Piloten sind verschiedene Prüfungsfragen. Der Schritt von der einen zur anderen muss begründet werden.</div></section><section class="section grid"><article class="card"><h2>Menschenwürde und Lebensrecht</h2><p>Art. 1 GG bindet die staatliche Gewalt an die Achtung und den Schutz der Menschenwürde. Art. 2 GG gewährleistet unter anderem das Recht auf Leben. Beide Perspektiven gelten auch für Menschen, die sich in einer scheinbar ausweglosen Lage befinden.</p><p>Das BVerfG erklärte 2006 die damalige gesetzliche Abschussermächtigung für nichtig. Für Unbeteiligte an Bord steht die Grenze im Zentrum, sie nicht zum blossen Objekt einer staatlichen Rettungsaktion zu machen.</p>${source('gg1')}${source('gg2')}${source('bverfg')}</article><article class="card"><h2>Notstand genau unterscheiden</h2><p><b>§ 34:</b> rechtfertigender Notstand. Gegenwärtige, nicht anders abwendbare Gefahr, wesentlich überwiegendes Interesse und Angemessenheit sind zentrale Anforderungen. Der Normtext gibt keine pauschale Erlaubnis, Menschenleben zahlenmässig aufzurechnen.</p><p><b>§ 35:</b> entschuldigender Notstand. Er erfasst unter weiteren Voraussetzungen Gefahren für die handelnde Person, Angehörige oder andere nahestehende Personen. Die Stadionbesuchenden bilden im Stück nicht diesen Nähekreis.</p><p><b>Übergesetzlicher entschuldigender Notstand:</b> umstrittene aussergesetzliche Figur, auf die das Stück seine Urteilsalternativen zuspitzt. Keine allgemeine Ausnahmevollmacht.</p>${source('st34')}${source('st35')}</article></section><section class="section card"><h2>Acht Begriffe und Unterscheidungen prüfen</h2><p class="muted">Hier sind die Antworten überprüfbar. Die Rückmeldung betrifft Begriffskenntnis, nicht dein persönliches moralisches Votum.</p>${D.quizzes.map((q,i)=>`<div class="question"><h3>${i+1}. ${q.q}</h3><div class="options">${q.o.map((o,j)=>`<button data-law="${i}" data-option="${j}" class="${state.answers['law-'+i]===j?'selected':''}">${o}</button>`).join('')}</div><div id="lawFeedback${i}" role="status">${state.answers['law-'+i]!==undefined?`<div class="response ${state.answers['law-'+i]===q.a?'':'wrong'}">${state.answers['law-'+i]===q.a?'Richtig unterschieden.':'Noch einmal unterscheiden.'} ${q.f}</div>`:''}</div></div>`).join('')}</section><section class="section grid"><div class="card"><h2>Dein begründetes Urteil</h2><p>Schreibe 350–500 Wörter. Trenne das moralische Urteil von der rechtlichen Prüfung und benenne eine offene Streitfrage.</p>${note('urteil-these','Urteil · Ergebnis und Massstab')}${note('urteil-belege','Urteil · Zwei Belege und ihre Tragweite')}${note('urteil-einwand','Urteil · Stärkster Einwand und Antwort')}${note('urteil-grenze','Urteil · Rechtliche Unsicherheit und Grenze')}${rubric('urteil')}</div><div class="card"><h2>Der Schweizer Vergleich</h2><p>Lies Art. 7, 10 und 36 der Bundesverfassung. Vergleiche Würdeschutz, Lebensrecht, Verhältnismässigkeit und unantastbaren Kerngehalt.</p><p>Der Vergleich von Grundrechten genügt nicht, um einen Schweizer Abschussfall strafrechtlich zu lösen. Zuständigkeiten, Befugnisse und Strafrecht müssten eigenständig untersucht werden.</p>${source('bv')}${note('schweiz','Rechtsvergleich Deutschland – Schweiz','Gemeinsames Schutzanliegen · unterschiedlicher Normtext · Grenze des Vergleichs')}<h3>Woran erkennst du Fortschritt?</h3><p>Du unterscheidest erlaubte Handlung, entschuldigte Person und mildere Sanktion. Du kannst einen Freispruch oder eine Verurteilung diskutieren, ohne Verfassungsrecht und Strafrecht gleichzusetzen.</p></div></section>`;}
function simulation(){const stage=state.sim.stage;if(stage>=D.simStages.length)return head('VERHANDLUNG / BERATUNG','Jetzt trägst du die Begründung.','Die Simulation hat deine Prüfungsschritte begleitet. Sie fällt kein automatisches Urteil.')+`<div class="grid"><section class="card"><h2>Deine Entscheidung</h2><p>Anfangsvotum: <b>${escape(state.votes.initial||'noch nicht festgehalten')}</b></p><label class="field"><span>Votum nach der Verhandlung</span><select id="finalVote"><option value="">Bitte wählen</option>${['Verurteilung befürwortet','Freispruch befürwortet','Urteil bleibt offen'].map(v=>`<option ${state.votes.final===v?'selected':''}>${v}</option>`).join('')}</select></label>${note('sim-urteil','Verhandlung · Begründetes Schlussvotum','Nenne Tatsachenbasis, Norm, Gegenargument und Antwort. Bei offenem Votum: Welche Frage verhindert die Entscheidung?')}${note('sim-wandel','Verhandlung · Was sich in meinem Denken verändert hat','Vergleiche mit deinem Anfangsvotum. Auch eine präzisere Begründung desselben Ergebnisses ist ein Lernfortschritt.')}${rubric('simulation')}<a class="button accent" href="#lektuere/urteile">Mit beiden Stückenden vergleichen</a></section><section class="card"><h2>Dein Prüfungsprotokoll</h2>${D.simStages.map((s,i)=>`<p><b>${s.title}</b><br>${escape(s.options[state.sim.answers[i]]||'Noch nicht beantwortet')}</p>`).join('')}<button class="secondary" data-sim-prev>Zum letzten Schritt zurück</button></section></div><section class="section card"><h2>Nachgespräch</h2><p>Was hat dein Urteil stärker beeinflusst: eine Information, eine Norm oder die Sympathie für eine Figur? Formuliere eine dritte Frage, die die binäre Abstimmung nicht erfassen konnte.</p>${note('sim-debrief','Verhandlung · Nachgespräch')}</section>`;
const s=D.simStages[stage],choice=state.sim.answers[stage];return head('SELBSTLERN-SIMULATION / SCHRITT '+(stage+1)+' VON '+D.simStages.length,'Der Fall wird verhandelt.','Du übernimmst nacheinander die Perspektive der Verfahrensleitung. Lies jede Gegenstimme und begründe deinen nächsten Schritt.')+`<div class="workspace-grid"><section class="card"><span class="tag lime">${stage+1} / ${D.simStages.length}</span><h2 style="margin-top:20px">${s.title}</h2><p class="lead">${s.text}</p><h3>${s.question}</h3><div class="options">${s.options.map((o,i)=>`<button class="${choice===i?'selected':''}" data-sim-choice="${i}">${o}</button>`).join('')}</div><div id="simFeedback" role="status">${choice!==undefined?`<div class="callout">${s.feedback[choice]}</div>`:''}</div>${note('sim-'+stage,s.title+' · Prüfnotiz','Notiere eine Anschlussfrage oder begründe, warum du deine Auswahl revidierst.')}<div class="choice-row"><button class="secondary" data-sim-prev ${stage===0?'disabled':''}>Zurück</button><button class="accent" data-sim-next ${choice===undefined?'disabled':''}>${stage===D.simStages.length-1?'Zur Urteilsberatung':'Nächster Verhandlungsschritt'}</button></div></section><aside class="card"><h2>Deine Arbeitsregeln</h2>${list(['Trenne Figurenwissen und späteres Wissen.','Behandle Aussagen als prüfbare Beiträge, nicht als vollständige Wahrheit.','Prüfe die stärkste Gegenposition.','Leite aus einer Rettungsabsicht keine automatische Erlaubnis ab.','Halte Literatur, Moral und Recht auseinander.'])}<div class="callout">Diese Simulation folgt festen didaktischen Verzweigungen. Sie erfindet keine Zeugenaussagen und bewertet keine freien Texte automatisch.</div><p><a href="#rollen">Rollenakte nachschlagen</a></p><p><a href="#recht">Rechtsbegriffe nachschlagen</a></p><p><a href="#philosophie">Denkposition nachschlagen</a></p></aside></div>`;}
function film(id){const v=D.videos.find(v=>v.id===id);if(!v)return head('FILMVISIONIERUNG & WERKSTATT / SEHEN UND VERGLEICHEN','Nicht nur die Geschichte sehen.<br>Die Inszenierung lesen.','Arbeite vor, während und nach der Sichtung. Wähle kurze Ausschnitte und halte deine Beobachtungen mit Zeitmarken fest.')+`<section class="card entry-path"><h2>Den Film Szene für Szene erschliessen</h2><p>Die zwölf Lektürestationen führen dich mit Filmabschnitten, passenden PDF-Seiten und Aufgaben durch das Stück. Beginne mit dem Auftakt; die weiteren Videos und Vergleichsaufträge hier ergänzen deine Sichtung.</p><a class="button" href="#lektuere/auftakt">Kuratierte Szenenvisionierung starten →</a> <a href="#lektuere">Alle zwölf Stationen ansehen</a></section><div class="grid">${D.videos.map((v,i)=>linkCard('film/'+v.id,'FILM '+(i+1),v.title,v.before,v.kind)).join('')}</div><section class="section card"><h2>Sechs Szenenfenster für die Verfilmung</h2><p>Im <a href="#lektuere/auftakt">Szenenleseraum</a> sind die Filmabschnitte bereits mit PDF-Seiten und Aufträgen verknüpft. Für eigene Vergleiche kannst du hier zusätzliche Ausschnitte festlegen.</p><div class="table-wrap"><table><thead><tr><th>Fenster</th><th>Textbezug</th><th>Beobachtungsfrage</th></tr></thead><tbody>${[['Eröffnung','PDF 7–12','Wie erzeugen Raum, Kostüm und Blickrichtung Autorität?'],['Lauterbach und Räumung','PDF 35–42','Wem gehört die Kamera während einer schwierigen Frage?'],['Kochs Befragung','PDF 43–64','Erzeugt die Nahaufnahme Gewissheit oder Verletzlichkeit?'],['Meisers Aussage','PDF 65–73','Wie werden Erinnerung, Pause und Reaktion der anderen gestaltet?'],['Plädoyers','PDF 75–84','Welche Rede erhält welche Bild- und Tonunterstützung?'],['Urteil','PDF 87–93','Wie prägt der Schnitt die Bewertung des Schlusses?']].map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div></section>`;
return `<p class="breadcrumb"><a href="#film">Filmwerkstatt</a> / ${v.title}</p>`+head(v.kind,v.title)+`<div class="workspace-grid"><section class="stack"><div class="card"><div id="videoMount" class="video-frame"><div><p style="color:white">Der Player wird erst auf deinen Klick geladen.</p><button class="accent" data-load-video="${v.id}">Video hier laden</button><p style="color:#becfda;font-size:.8rem;margin:12px 0 0">Beim Laden wird eine Verbindung zu ${v.youtube?'YouTube':'Dropbox'} hergestellt.</p></div></div><p>${external(v.url,'Bei der Quelle öffnen')}</p><p class="notice muted">${v.note}</p>${v.id==='film'?`<div class="clip-toolbar"><label class="field"><span>Start (mm:ss)</span><input id="clipStart" type="text" inputmode="numeric" placeholder="z. B. 12:30"></label><label class="field"><span>Ende (mm:ss)</span><input id="clipEnd" type="text" inputmode="numeric" placeholder="z. B. 14:10"></label><button class="secondary" data-play-clip>Ausschnitt abspielen</button></div><div class="choice-row"><button class="secondary small" data-mark-time="start">Aktuelle Zeit als Start</button><button class="secondary small" data-mark-time="end">Aktuelle Zeit als Ende</button></div><label class="field"><span>Titel deines Ausschnitts</span><input id="clipTitle" type="text" placeholder="z. B. Meisers Aussage: Pause und Blick"></label><button class="secondary" data-save-clip>Ausschnitt im Journal sichern</button><div id="clipMessage" role="status"></div>${details('Falls die Wiedergabe nicht startet',`<p>Öffne die verlinkte Quelle. Alternativ kannst du eine eigene lokal vorhandene Filmdatei auswählen; sie wird nicht hochgeladen. Der grosse Dropbox-Film kann je nach Verbindung verzögert starten.</p><label class="field"><span>Eigene Filmdatei öffnen</span><input type="file" id="localFilm" accept="video/*"></label>`)}<div id="savedClips">${renderClips()}</div>`:''}</div><section class="card"><h2>Dein Szenenprotokoll</h2>${note('film-beobachtung-'+id,v.title+' · Beobachtungsprotokoll','Zeitmarke → Einstellung / Ton / Spiel → Wirkungshypothese → Textbezug')}${note('film-vergleich-'+id,v.title+' · Vergleich und Deutung','Welche Wirkung ist im Text angelegt, welche entsteht durch das Medium?')}${rubric('film-'+id)}</section></section><aside class="stack"><section class="card"><h3>Vor der Sichtung</h3><p>${v.before}</p><h3>Während der Sichtung</h3><p>${v.during}</p><h3>Nach der Sichtung</h3><p>${v.after}</p></section><section class="card"><h3>Dein Filmvokabular</h3><p><b>Einstellungsgrösse:</b> Totale, Halbtotale, Nahaufnahme, Detail.</p><p><b>Perspektive:</b> Augenhöhe, Aufsicht, Untersicht; subjektiver oder beobachtender Blick.</p><p><b>Montage:</b> Reihenfolge und Dauer der Einstellungen; Reaktionsschnitt, Schuss–Gegenschuss.</p><p><b>Ton:</b> Stimme, Raumgeräusch, Musik, Stille; hörbare und sichtbare Quelle.</p><p><b>Spiel:</b> Blick, Haltung, Sprechtempo, Pausen und Distanz.</p><div class="callout">Keine Form hat immer dieselbe Wirkung. Erkläre sie am konkreten Ausschnitt.</div></section></aside></div>`;}
function renderClips(){return state.clips.length?`<h3 style="margin-top:25px">Deine Ausschnitte</h3>${state.clips.map((c,i)=>`<p><button class="secondary small" data-open-clip="${i}">${escape(c.title)} · ${fmtTime(c.start)}–${fmtTime(c.end)}</button> <button class="secondary small" data-delete-clip="${i}" aria-label="Ausschnitt ${escape(c.title)} entfernen">Entfernen</button></p>`).join('')}`:'';}
function fmtTime(n){return Math.floor(n/60)+':'+String(Math.floor(n%60)).padStart(2,'0');}
function parseTime(s){if(!/^\d{1,3}:[0-5]\d$/.test(s.trim()))return NaN;const [m,sec]=s.split(':').map(Number);return m*60+sec;}
function attachVideo(v){currentVideo=v;const mount=document.getElementById('videoMount');if(v.youtube){mount.innerHTML=`<iframe title="${escape(v.title)}" src="https://www.youtube-nocookie.com/embed/${v.youtube}?start=${v.start||0}" allow="fullscreen; encrypted-media; picture-in-picture" referrerpolicy="strict-origin-when-cross-origin" allowfullscreen></iframe>`;}else{mount.innerHTML='<video id="filmPlayer" controls preload="metadata" playsinline aria-label="Terror – Ihr Urteil"></video>';const video=document.getElementById('filmPlayer');video.src=filmObjectURL||v.src;video.addEventListener('timeupdate',()=>{if(clipEnd!==null&&video.currentTime>=clipEnd){video.pause();clipEnd=null;}});video.addEventListener('error',()=>{document.getElementById('clipMessage').innerHTML='<div class="callout warn">Der Film kann in diesem Browser nicht geladen werden. Öffne die Quelle oder wähle eine lokale Filmdatei.</div>';});}}
async function playClip(start,end){let video=document.getElementById('filmPlayer');if(!video){attachVideo(D.videos[0]);video=document.getElementById('filmPlayer');}document.getElementById('clipMessage').textContent='Ausschnitt wird vorbereitet …';const run=async()=>{if(Number.isFinite(video.duration)&&end>video.duration){document.getElementById('clipMessage').textContent='Das Ende liegt ausserhalb der Filmlänge.';return;}clipEnd=end;video.currentTime=start;try{await video.play();document.getElementById('clipMessage').textContent=`Ausschnitt ${fmtTime(start)}–${fmtTime(end)}. Die Wiedergabe stoppt am Ende.`;}catch(e){document.getElementById('clipMessage').textContent='Bitte starte den Player manuell oder öffne die Quelle.';}};if(video.readyState>=1)await run();else video.addEventListener('loadedmetadata',run,{once:true});}
function politics(id){const p=D.politics.find(p=>p.id===id);if(p)return `<p class="breadcrumb"><a href="#politik">Politik & Weltbilder</a> / ${p.title}</p>`+head('POLITISCHE LEKTÜRE',p.title,p.intro)+`<div class="workspace-grid"><section class="card"><h2>Deine Untersuchung</h2>${list(p.tasks)}${note('politik-'+id,p.title+' · Analyse')}${details('Vergleichshorizont',p.model)}${rubric('politik-'+id)}${source(p.source)}${id==='rezeption'?source('zeit'):''}</section><aside class="card"><h2>Kontrovers und präzise</h2><p>Formuliere zuerst eine These, dann ihre stärkste Gegenposition. Unterscheide dabei:</p>${list(['beschreibende Behauptungen: Was ist?','erklärende Behauptungen: Warum geschieht es?','normative Behauptungen: Was soll gelten?'])}${note('politik-gegen-'+id,p.title+' · Gegenposition und Antwort')}<p><a href="#philosophie">Philosophische Voraussetzungen prüfen</a></p></aside></div>`;
return head('GESELLSCHAFT / MACHT / WELTANSCHAUUNG','Welche Ordnung verteidigst du?','Das Stück stellt nicht nur eine persönliche Entscheidung aus. Es verhandelt Bilder von Staat, Freiheit, Bedrohung und Zusammenleben.')+`<section class="card"><h2>Kontext in fünf Schritten</h2><div class="timeline"><article><b>2001 · HISTORISCHER KONTEXT</b><p>Die Anschläge vom 11. September prägen Sicherheitsdebatten und die Frage nach dem Umgang mit entführten Flugzeugen.</p></article><article><b>2006 · VERFASSUNGSRECHT</b><p>Das Bundesverfassungsgericht erklärt die damalige Abschussermächtigung für nichtig.</p></article><article><b>2013 · FIKTIVE HANDLUNGSZEIT</b><p>Die Anklage im Stück datiert Kochs Tat auf den 26. Mai 2013. Das ist kein Bericht eines realen Strafverfahrens.</p></article><article><b>2015 · DRAMA</b><p>«Terror» erscheint und wird uraufgeführt. Das Publikum entscheidet zwischen zwei vorgegebenen Enden.</p></article><article><b>2016 · FERNSEHEN UND REZEPTION</b><p>Die Verfilmung und die Publikumsabstimmung erweitern die Diskussion über Recht und die Verantwortung der Medien.</p></article></div>${source('folgen')}${source('bverfg')}${source('srf')}</section><section class="section grid three">${D.politics.map((p,i)=>linkCard('politik/'+p.id,String(i+1).padStart(2,'0'),p.title,p.intro)).join('')}</section><section class="section card"><h2>Eine eigene Gegenöffentlichkeit gestalten</h2><p>Wähle ein Produkt: Kommentar, Podcast-Skript, Programmheft oder kurze Erklärvideo-Skizze. Formuliere eine Leitfrage, rekonstruiere mindestens zwei Positionen fair und lege die eigenen Quellen offen.</p>${note('politik-produkt','Mein öffentliches Argument','Adressaten · Leitfrage · These · Gegenposition · Belege · Formatentscheidungen')}${checklist('politikprodukt',['Ich trenne fiktiven Fall und historische Ereignisse.','Ich vermeide Kollektivzuschreibungen an Religionen oder politische Gruppen.','Ich begründe, warum mein Medium zur Aussage passt.','Ich kennzeichne Unsicherheit und fremde Positionen.'])}</section>`;}
function games(){return head('DEINE VORHANDENEN LERNSPIELE','Spielen. Prüfen. Zurück zum Text.','Die Spiele öffnen in einem neuen Tab. Vorbereitung und Reflexion machen aus einer Entscheidung einen Lernprozess.')+`<div class="stack">${D.games.map((g,i)=>`<article class="card"><div class="section-head"><div><span class="eyebrow">SPIEL ${i+1} · ${g.mode}</span><h2>${g.name}</h2></div>${external(g.url,'Spiel öffnen')}</div><div class="grid three"><div><h3>Vorher</h3><p>${g.before}</p></div><div><h3>Im Spiel</h3><p>${g.during}</p></div><div><h3>Danach</h3><p>${g.after}</p></div></div>${note('spiel-'+i,g.name+' · Reflexion','Welche Annahme steckt in den Spielregeln? Welche Textstelle stützt oder irritiert das Ergebnis?')}<p class="source">${g.verified}</p></article>`).join('')}</div>`;}
function journal(){const entries=Object.entries(state.notes).filter(([,v])=>v.text?.trim());return head('DEIN JOURNAL / LOKALE ARBEIT','Die Entwicklung deiner Gründe.','Sichere deine Arbeit als Datei oder drucke sie. Auf dieser Website werden deine Antworten nicht an eine Lehrperson oder einen KI-Dienst übertragen.')+`<div class="choice-row no-print"><button data-export="md" class="accent">Journal als Text exportieren</button><button data-export="json" class="secondary">Sicherung herunterladen</button><button data-print class="secondary">Drucken / als PDF sichern</button></div><div class="grid section"><section class="card"><h3>Dein Stand</h3><p><b>${state.done.length} / ${D.modules.length}</b> Lektürestationen reflektiert · <b>${entries.length}</b> Notizen · <b>${state.clips.length}</b> Filmausschnitte</p><p>Anfangsvotum: ${escape(state.votes.initial||'offen')}<br>Schlussvotum: ${escape(state.votes.final||'noch nicht festgehalten')}</p><p class="notice muted">«Reflektiert» ist deine eigene Markierung und keine automatische Leistungsbewertung.</p></section><section class="card no-print"><h3>Auf einem anderen Gerät weiterarbeiten</h3><p class="notice">Importiere eine zuvor exportierte JSON-Sicherung. Neue Notizen werden ergänzt; bei gleichen Einträgen wird die jüngere Notiz behalten.</p><label class="field"><span>Sicherung importieren</span><input type="file" id="importJournal" accept="application/json,.json"></label><div id="importFeedback" role="status"></div></section></div><section class="section card"><h2>Deine Notizen</h2>${entries.length?entries.map(([k,v])=>`<article class="journal-item"><h3>${escape(v.label||k)}</h3><p>${escape(v.text)}</p><a class="no-print" href="#${escape(v.route||'start')}">An der Lernstation weiterarbeiten</a></article>`).join(''):'<p>Noch keine Notizen. Beginne mit einem ersten Grund im <a href="#start">Arbeitsraum</a> oder einer <a href="#lektuere">Lektürestation</a>.</p>'}</section>${state.clips.length?`<section class="section card"><h2>Deine Filmstellen</h2>${state.clips.map(c=>`<p><b>${escape(c.title)}</b> · ${fmtTime(c.start)}–${fmtTime(c.end)}</p>`).join('')}<p><a href="#film/film">Im Filmwerkzeug öffnen</a></p></section>`:''}<section class="section card no-print"><h3>Lokale Daten verwalten</h3>${details('Alle lokalen Einträge löschen',`<p>Dies entfernt Notizen, Markierungen, Quizantworten und Filmausschnitte aus diesem Browser. Exportiere zuerst eine Sicherung, wenn du sie behalten möchtest.</p><label><input type="checkbox" id="confirmDelete">Ich möchte meine lokalen Lerndaten löschen.</label><p><button class="secondary" data-clear>Lokale Lerndaten löschen</button></p>`)}</section>`;}
function sources(){return head('QUELLEN / TRANSPARENZ','Worauf diese Lernumgebung beruht.','Textbelege, didaktische Deutungen, Rechtsquellen und externe Medien haben unterschiedliche Funktionen. Quellenprüfung: 30. September 2026.')+`<section class="card"><h2>Die beiden bereitgestellten PDF-Dateien</h2><h3>Ferdinand von Schirach: Terror</h3><p><i>Terror. Ein Theaterstück und eine Rede.</i> btb, Neuausgabe Oktober 2016. eISBN 978-3-641-20329-0. Datei: Schirach_Terror_9783641203290.pdf, 103 PDF-Seiten.</p><p>Primärtext für Figuren, Handlungsdetails und Lektüreaufträge. Die Stationen beziehen sich auf die PDF-Zählung: Auftakt S. 7–12, Lauterbach S. 17–42, Koch S. 43–64, Meiser S. 65–73, Plädoyers S. 75–84, Urteile S. 87–93, Rede S. 95–103. Die bereitgestellte Buchdatei ist im Leseraum eingebunden und öffnet sich automatisch an der passenden Textstelle. Optional kannst du eine eigene PDF-Ausgabe verwenden.</p><h3>Matthias Knopp u. a. (Hrsg.): Sprachliche Bildung in der digitalisierten Gesellschaft</h3><p><i>Was wir in Zukunft wissen und können müssen.</i> 2022. Datei: 4555Volltext.pdf, 420 PDF-Seiten. Kein Sekundärtext zum Drama.</p><p>Gezielt ausgewertet: Thomas Riecke-Baulecke, S. 119–123 (aktive digitale Lernarrangements); Hans-Joachim Roth, S. 125–140 (Aufmerksamkeit, Reflexion und eigene Positionierung im Umgang mit Propaganda); Jörg Jost und Elmar Souvignier, S. 269 ff. (Verknüpfung von Diagnose, Rückmeldung und Förderung).</p><p>Die Übertragung dieser Ansätze auf «Terror», alle Aufträge, Rollenimpulse und Simulationstexte sind eigene didaktische Ausarbeitungen. Es wird keine empirisch nachgewiesene Wirksamkeit dieser konkreten Website behauptet.</p></section><section class="section grid">${Object.entries(D.sources).map(([id,s])=>`<article class="card"><span class="eyebrow">${s.type}</span><h3>${external(s.url,s.title)}</h3><p>${s.note}</p></article>`).join('')}</section><section class="section card"><h2>Medien und Lernspiele</h2><p><a href="#flydubai/quellen">Fallakte Flydubai: Nachrichten und Originalmitteilungen</a> · <a href="#flydubai/filme">Zwei DW-Filmbeiträge</a>. Separater Quellenstand: 1. Oktober 2026. Laufende Untersuchung; zugeschriebene Aussagen und offene Fragen sind gekennzeichnet.</p><p><a href="#aviatik">Aviatische Fachquellen, Flugkarten und Bildnachweise</a>: DFS, EUROCONTROL, FAA, Bundeswehr und frei lizenzierte Fotografien. Reale Informationen, Dramentext und Unterrichtsmodelle werden getrennt gekennzeichnet.</p><p>Die Bildgestaltung verwendet 14 Standbilder und sechs Ausschnitte von jeweils 20 Sekunden aus der bereitgestellten Fassung von «Terror – Ihr Urteil». Zeitmarken stehen bei den Bildern und Szenenfenstern. Die Auswahl dient der Analyse von Inszenierung, Auftreten und Perspektive; der Kontext ist über die jeweilige Lektürestation erreichbar.</p>${D.videos.map(v=>`<p><b>${external(v.url,v.title)}</b><br>${v.note}</p>`).join('')}${D.games.map(g=>`<p><b>${external(g.url,g.name)}</b><br>${g.verified}</p>`).join('')}</section><section class="section card"><h2>Grenzen und Arbeitsweise</h2><p>Die juristischen Erläuterungen sind eine didaktische Einführung zum literarischen Fall. Die Entscheidung von 2006 wird in ihrem historischen Zusammenhang behandelt; militärische Einsatzbefugnisse insgesamt werden nicht als unverändert dargestellt.</p><p>Offene Interpretationen werden nicht automatisch benotet. Die 36 Lektüreaufträge bieten einen lokalen Sprachabgleich mit Synonymen, Wortformen und vorsichtiger Erkennung sachlicher Widersprüche. Das Sofortfeedback nennt erkannte Aspekte, Ergänzungshinweise, Referenzantworten und konkrete PDF-Fundstellen. Es ist keine vollständige semantische Prüfung; abweichende belegte Lesarten bleiben möglich. Kurzchecks prüfen begrenzte Begriffs- und Textunterscheidungen. Die Verhandlung und die Gegenfragen folgen festen, transparenten Antwortwegen.</p><p>Für die bereitgestellte Spielfilmfassung (93:37) wurden die Dialoge lokal zur Orientierung transkribiert und die Kapitelgrenzen mit Textstellen und Filmbildern abgeglichen. Die didaktischen Kapitel sind keine offiziellen Filmszenen. Die übrigen Videos sind nicht vollständig gesichtet oder transkribiert. Die Filmwerkstatt bietet zusätzlich selbst zu bestimmende Ausschnitte. Bei ZEIT ist der Volltextzugriff ungeprüft beziehungsweise eingeschränkt.</p><p>Notizen werden lokal gespeichert. Externe Quellen und Player haben eigene Zugangs- und Datenschutzbedingungen; Player laden erst nach bewusster Auswahl. Diese Fassung enthält weder Klassenkonten noch eine Live-Abstimmung.</p></section>`;}
function teacher(){return head('FÜR LEHRPERSONEN','Offene Wege, klare Kriterien.','Die Umgebung richtet sich an die gymnasiale Oberstufe und ist für überwiegend selbstständige Arbeit ausgelegt.')+`<section class="grid"><div class="card"><h2>Lernziele</h2>${list(['Dialog, Regieanweisung und Publikumsansprache funktionsbezogen analysieren.','Figurenperspektiven textgestützt rekonstruieren und kreative Ergänzungen markieren.','Behauptung, Beleg, Schlussregel und Gegenargument unterscheiden.','Moralisches Urteil, Verfassungsfrage und Strafbarkeitsprüfung auseinanderhalten.','Filmische Gestaltung mit dem Dramentext vergleichen.','Politische Rahmungen und Grenzen von Gedankenexperimenten reflektieren.'])}</div><div class="card"><h2>Selbstständigkeit unterstützen</h2><p>Jede Lektürestation bietet Ziel, Textfenster, Analyseaufträge, gestufte Hilfen und einen Vergleichshorizont. Die Lernenden wählen ihren Zugang selbst.</p><p>Als gemeinsame Mindestgrundlage eignen sich Auftakt, Meiser, beide Plädoyers sowie die Begriffe Rechtfertigung und Entschuldigung. Darauf können individuelle Vertiefungen aufbauen.</p><p>Der Export dient als Abgabeformat. Eine Lehrpersonenansicht fremder Journale und eine zentrale Speicherung sind nicht eingerichtet.</p></div></section><section class="section card"><h2>Bewertungsraster für ein Portfolio</h2><div class="table-wrap"><table><thead><tr><th>Kriterium</th><th>Grundlegend</th><th>Solide</th><th>Differenziert</th></tr></thead><tbody>${[['Textbezug','Behauptung mit vereinzelter Fundstelle','Passende Belege werden erklärt','Gegenbelege und Grenzen werden einbezogen'],['Interpretation','Inhalt wird überwiegend wiedergegeben','Form und Wirkung werden verbunden','Mehrdeutigkeit wird am Text begründet'],['Argumentation','Position mit einfachem Grund','These, Beleg und Schlussregel sind erkennbar','Starke Gegenposition wird fair geprüft'],['Recht und Philosophie','Begriffe teilweise unscharf','Ebenen und Positionen werden unterschieden','Übertragungen und Streitfragen werden begrenzt'],['Medienreflexion','Allgemeine Wirkungseindrücke','Konkrete Gestaltung mit Zeitmarken','Text, Medium und Rezeptionsrahmen werden verglichen'],['Revision','Erste Antwort bleibt unkommentiert','Änderungen werden benannt','Lernfortschritt wird an Belegen gezeigt']].map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="source">Eigenes didaktisches Raster. Kein standardisiertes Testinstrument. Die politische oder moralische Entscheidung selbst wird nicht benotet.</p></section><section class="section grid"><div class="card"><h2>Leistungsprodukte zur Wahl</h2><p><b>Interpretationsdossier:</b> zwei eng gelesene Passagen, eine alternative Deutung und ein begründetes Fazit.</p><p><b>Rollenportfolio:</b> Textanker, Rollenrede, Gegenfrage, szenische Entscheidungen und Distanzierung.</p><p><b>Urteilsessay:</b> getrennte moralische und rechtliche Prüfung, stärkster Einwand, offen ausgewiesene Unsicherheit.</p><p><b>Filmvergleich:</b> drei Einstellungen mit Zeitmarken, Textvergleich und begründete Wirkungsthese.</p></div><div class="card"><h2>Diskussion verantworten</h2><p>Vermeide eine öffentliche Zuordnung persönlicher Überzeugungen zu Schulnoten oder festen Rollen. Rollenübernahme kann durch beobachtende Analyse ersetzt werden.</p><p>Kontroverse Positionen werden geprüft, Menschenwürde und die Gleichwertigkeit von Personen nicht zur Mehrheitsfrage gemacht. Religiöse oder politische Kollektivzuschreibungen werden analytisch aufgelöst.</p><p>Das Thema umfasst Tod, Gewalt und Verlust. Die Aufgaben verlangen keine persönlichen Trauer- oder Gewalterfahrungen. Die Textanalyse ist immer eine Alternative zur szenischen Darstellung.</p>${source('beutelsbach')}</div></section><section class="section card"><h2>Eine Verhandlung in der Gruppe</h2>${list(['Verteile Prozessrollen und Beobachtungsaufträge. Die Rollenakten geben Belege und Wissensgrenzen vor.','Lasse die Beteiligten zuerst Aussagen und Fragen vorbereiten; neue Tatsachen dürfen nicht erfunden werden.','Spiele Vernehmungen und zwei gleich lange Plädoyers. Beobachtende protokollieren Texttreue und Schlussregeln.','Trenne die anonyme Abstimmung von der individuellen schriftlichen Begründung.','Beende das Spiel mit einer ausdrücklichen Rollenentlassung und einer Reflexion der Fallkonstruktion.'])}<button data-print class="secondary">Hinweise drucken</button></section>`;}
function missing(){return head('ORIENTIERUNG','Diese Station gibt es nicht.')+'<a class="button" href="#start">Zum Arbeitsraum</a>';}
function render(){document.querySelectorAll('.film-window video').forEach(v=>v.pause());stopReader();const raw=location.hash.slice(1)||'lektuere';const [route,id]=raw.split('/');clipEnd=null;currentVideo=null;const views={grundlagen:foundationBasics,befehlskette:foundationChain,geschichte:foundationHistory,start,lektuere:reading,rollen:roles,dilemma,recht:law,philosophie:philosophy,simulation,film,aviatik:aviation,flydubai,politik:politics,spiele:games,journal,quellen:sources,lehrperson:teacher};main.classList.toggle('is-reader',route==='lektuere'&&!!id);main.innerHTML=foundationCard(route,id)+(views[route]||missing)(id)+((route==='lektuere'&&(!id||['auftakt','meiser','koch','grenzfaelle'].includes(id)))||route==='aviatik'&&!id?fzEntry():'')+(route==='lektuere'&&id?'':visualWindows(route,id));if(route==='lektuere'&&id)initReader();if(route==='aviatik')initAviation();initFoundations();document.querySelectorAll('#nav a').forEach(a=>{const active=a.getAttribute('href')==='#'+route;a.classList.toggle('active',active);active?a.setAttribute('aria-current','page'):a.removeAttribute('aria-current');});document.title=(navs.find(n=>n[0]===route)?.[1]||'TERROR')+' · TERROR';updateProgress();if(route==='philosophie')comparePhilo();window.scrollTo(0,0);}
function exportData(type){const entries=Object.values(state.notes).filter(v=>v.text?.trim());let text,mime,name;if(type==='json'){text=JSON.stringify({format:'terror-journal-v1',exported:new Date().toISOString(),state},null,2);mime='application/json';name='terror-journal-sicherung.json';}else{text='# TERROR · Mein Arbeitsjournal\n\nExport: '+new Date().toLocaleDateString('de-CH')+'\n\nAnfangsvotum: '+(state.votes.initial||'offen')+'\nSchlussvotum: '+(state.votes.final||'offen')+'\n\n'+entries.map(n=>'## '+n.label+'\n\n'+n.text+'\n').join('\n')+'\n## Filmausschnitte\n\n'+state.clips.map(c=>'- '+c.title+': '+fmtTime(c.start)+'–'+fmtTime(c.end)).join('\n');mime='text/markdown;charset=utf-8';name='terror-arbeitsjournal.md';}const url=URL.createObjectURL(new Blob([text],{type:mime}));const a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Journal exportiert.');}
function validImport(x){const s=x?.state;if(x?.format!=='terror-journal-v1'||!s||!s.notes||typeof s.notes!=='object'||Array.isArray(s.notes))throw Error('Keine gültige TERROR-Sicherung.');if(Object.keys(s.notes).length>2000)throw Error('Die Sicherung enthält zu viele Einträge.');for(const [k,v] of Object.entries(s.notes)){if(['__proto__','constructor','prototype'].includes(k)||!v||typeof v.text!=='string'||v.text.length>200000||typeof v.label!=='string'||!/^[-a-z0-9/]*$/i.test(v.route||'start'))throw Error('Ungültiger Journaleintrag.');}return s;}
main.addEventListener('input',e=>{const el=e.target;if(el.dataset.note){state.notes[el.dataset.note]={text:el.value,label:el.dataset.label,route:location.hash.slice(1)||'lektuere',updated:Date.now()};save();}});
main.addEventListener('change',async e=>{const el=e.target;if(el.dataset.check){state.answers[el.dataset.check]=el.checked;save();}if(el.id==='finalVote'){state.votes.final=el.value;save();}if(el.id==='philoA'||el.id==='philoB')comparePhilo();if(el.id==='pdfInput'&&el.files[0]){const f=el.files[0];if(f.type!=='application/pdf'&&!f.name.toLowerCase().endsWith('.pdf')){toast('Bitte eine PDF-Datei wählen.');return;}if(pdfURL)URL.revokeObjectURL(pdfURL);pdfURL=URL.createObjectURL(f);const id=location.hash.split('/')[1],m=D.modules.find(m=>m.id===id);document.getElementById('pdfPanel').innerHTML=`<a href="${pdfURL}#page=${parseInt(m.pages)}" target="_blank" rel="noopener">${escape(f.name)} · Seite ${parseInt(m.pages)} öffnen</a>`;}if(el.id==='localFilm'&&el.files[0]){if(filmObjectURL)URL.revokeObjectURL(filmObjectURL);filmObjectURL=URL.createObjectURL(el.files[0]);attachVideo(D.videos[0]);toast('Lokale Filmdatei geöffnet.');}if(el.id==='importJournal'&&el.files[0]){try{if(el.files[0].size>10*1024*1024)throw Error('Die Sicherung ist grösser als 10 MB.');const s=validImport(JSON.parse(await el.files[0].text()));for(const [k,v] of Object.entries(s.notes)){if(!state.notes[k]||(Number(v.updated)||0)>(Number(state.notes[k].updated)||0))state.notes[k]={text:v.text,label:v.label,route:v.route||'start',updated:Number(v.updated)||Date.now()};}state.done=[...new Set([...state.done,...(Array.isArray(s.done)?s.done.filter(id=>D.modules.some(m=>m.id===id)):[])])];if(Array.isArray(s.clips)){for(const c of s.clips){if(typeof c.title==='string'&&Number.isFinite(c.start)&&Number.isFinite(c.end)&&c.start>=0&&c.end>c.start&&!state.clips.some(v=>v.title===c.title&&v.start===c.start&&v.end===c.end))state.clips.push({title:c.title.slice(0,200),start:c.start,end:c.end});}}if(s.votes&&typeof s.votes==='object'){if(!state.votes.initial&&['Eher verurteilen','Noch offen','Eher freisprechen'].includes(s.votes.initial))state.votes.initial=s.votes.initial;if(!state.votes.final&&['Verurteilung befürwortet','Freispruch befürwortet','Urteil bleibt offen'].includes(s.votes.final))state.votes.final=s.votes.final;}if(s.answers&&typeof s.answers==='object'&&!Array.isArray(s.answers)){for(const [k,v] of Object.entries(s.answers)){if(/^[-a-z0-9]+$/i.test(k)&&(typeof v==='boolean'||(Number.isInteger(v)&&v>=0&&v<10))&&state.answers[k]===undefined)state.answers[k]=v;}}if(s.sim&&Number.isInteger(s.sim.stage)&&s.sim.stage>=0&&s.sim.stage<=D.simStages.length&&s.sim.stage>state.sim.stage){const simAnswers={};for(let i=0;i<D.simStages.length;i++){const v=s.sim.answers?.[i];if(Number.isInteger(v)&&v>=0&&v<3)simAnswers[i]=v;}state.sim={stage:s.sim.stage,answers:simAnswers};}save();render();toast('Journal, Lernstand und Filmausschnitte importiert.');}catch(err){document.getElementById('importFeedback').textContent=err.message;}}});
main.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;const a=b.dataset;
if(a.vote){state.votes.initial=a.vote;save();document.querySelectorAll('[data-vote]').forEach(x=>x.setAttribute('aria-pressed',String(x.dataset.vote===a.vote)));document.getElementById('voteResult').textContent='Anfangsvotum: '+a.vote+'. Halte deinen ersten Grund daneben fest.';}
if(a.complete){const id=a.complete;state.done=state.done.includes(id)?state.done.filter(x=>x!==id):[...state.done,id];save();b.textContent=state.done.includes(id)?'Als reflektiert markiert':'Station als reflektiert markieren';b.setAttribute('aria-pressed',String(state.done.includes(id)));toast(state.done.includes(id)?'Reflexion markiert.':'Markierung entfernt.');}
if(a.filter){state.prefs.filter=a.filter;save();render();}
if(a.moduleCheck){const m=D.modules.find(x=>x.id===a.moduleCheck),ok=Number(a.option)===m.check.answer;const pages={auftakt:8,anklage:15,lauterbach:51,evakuierung:36,koch:52,grenzfaelle:55,meiser:68,nelson:78,biegler:84,urteile:88,dramenform:12,rede:95};document.getElementById('moduleFeedback').innerHTML=`<div class="response ${ok?'':'wrong'}"><b>${ok?'Richtig unterschieden.':'Diese Antwort ist nicht richtig.'}</b><p><b>Korrekte Antwort:</b> ${escape(m.check.options[m.check.answer])}</p><p><b>Begründung:</b> ${escape(m.check.feedback)}</p>${feedbackReference(pages[m.id],'Beleg und Kontext im Primärtext')}</div>`;}
if(a.reveal){const el=document.getElementById(a.reveal);el.hidden=false;b.hidden=true;}
if(a.dilemma){state.answers['dilemma-'+a.dilemma]=Number(a.option);save();document.querySelectorAll('[data-dilemma]').forEach(x=>x.setAttribute('aria-pressed',String(x.dataset.option===a.option)));document.getElementById('dilemmaFeedback').hidden=false;}
if('rawls' in a){const roles=['Du sitzt im Flugzeug. Welche Grenze soll der Staat dir garantieren?','Du sitzt im Stadion. Welche Schutzleistung darfst du vom Staat erwarten?','Du bist Pilot. Welche Regeln und institutionellen Hilfen brauchst du vor dem Ernstfall?'];state.prefs.rawls=roles[Math.floor(Math.random()*roles.length)];save();const r=document.getElementById('rawlsResult');r.hidden=false;r.textContent=state.prefs.rawls;}
if(a.law!==undefined){const i=Number(a.law),q=D.quizzes[i],j=Number(a.option);state.answers['law-'+i]=j;save();document.querySelectorAll(`[data-law="${i}"]`).forEach(x=>x.classList.toggle('selected',Number(x.dataset.option)===j));document.getElementById('lawFeedback'+i).innerHTML=`<div class="response ${j===q.a?'':'wrong'}">${j===q.a?'Richtig unterschieden.':'Noch einmal unterscheiden.'} ${q.f}</div>`;}
if(a.simChoice!==undefined){const i=Number(a.simChoice);state.sim.answers[state.sim.stage]=i;save();document.querySelectorAll('[data-sim-choice]').forEach(x=>x.classList.toggle('selected',Number(x.dataset.simChoice)===i));document.getElementById('simFeedback').innerHTML=`<div class="callout">${D.simStages[state.sim.stage].feedback[i]}</div>`;document.querySelector('[data-sim-next]').disabled=false;}
if('simNext' in a&&state.sim.answers[state.sim.stage]!==undefined){state.sim.stage=Math.min(D.simStages.length,state.sim.stage+1);save();render();}if('simPrev' in a){state.sim.stage=Math.max(0,state.sim.stage-1);save();render();}
if(a.loadVideo)attachVideo(D.videos.find(v=>v.id===a.loadVideo));
if(a.markTime){const v=document.getElementById('filmPlayer');if(!v||v.readyState<1){toast('Lade zuerst den Film und wähle eine Stelle.');return;}document.getElementById(a.markTime==='start'?'clipStart':'clipEnd').value=fmtTime(v.currentTime);}
if('playClip' in a||'saveClip' in a){const start=parseTime(document.getElementById('clipStart').value),end=parseTime(document.getElementById('clipEnd').value);if(!Number.isFinite(start)||!Number.isFinite(end)||end<=start){document.getElementById('clipMessage').textContent='Gib gültige Zeiten im Format mm:ss ein. Das Ende muss nach dem Start liegen.';return;}if('playClip' in a)await playClip(start,end);else{const title=document.getElementById('clipTitle').value.trim();if(!title){document.getElementById('clipMessage').textContent='Gib dem Ausschnitt einen Titel.';return;}state.clips.push({title:title.slice(0,200),start,end});save();document.getElementById('savedClips').innerHTML=renderClips();document.getElementById('clipMessage').textContent='Ausschnitt im Journal gespeichert.';}}
if(a.openClip!==undefined){const c=state.clips[Number(a.openClip)];document.getElementById('clipStart').value=fmtTime(c.start);document.getElementById('clipEnd').value=fmtTime(c.end);document.getElementById('clipTitle').value=c.title;await playClip(c.start,c.end);}if(a.deleteClip!==undefined){state.clips.splice(Number(a.deleteClip),1);save();document.getElementById('savedClips').innerHTML=renderClips();}
if(a.export)exportData(a.export);if('print' in a)window.print();if('clear' in a){if(!document.getElementById('confirmDelete').checked){toast('Bestätige zuerst das Löschen mit dem Kontrollkästchen.');return;}state={notes:{},done:[],answers:{},sim:{stage:0,answers:{}},clips:[],votes:{},prefs:{}};save();render();toast('Lokale Lerndaten gelöscht.');}
});
