if(document.modelContext?.registerTool){const life=new AbortController();const register=tool=>{try{Promise.resolve(document.modelContext.registerTool(tool,{signal:life.signal})).catch(()=>{});}catch(e){}};register({name:'read_learning_progress',title:'Lernstand lesen',description:'Liest lokale Reflexionsmarkierungen und die Anzahl eigener Notizen. Keine Benotung.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:()=>({reflectedModules:[...state.done],totalModules:D.modules.length,noteCount:Object.keys(state.notes).length})});register({name:'open_learning_station',title:'Lernstation öffnen',description:'Navigiert zu einer bestehenden Lernstation. Markiert nichts als erledigt.',inputSchema:{type:'object',properties:{moduleId:{type:'string',enum:D.modules.map(m=>m.id)}},required:['moduleId'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!input||!D.modules.some(m=>m.id===input.moduleId))throw Error('Unbekannte Lernstation.');history.replaceState(null,'','#lektuere/'+input.moduleId);render();return {opened:input.moduleId};}});window.addEventListener('pagehide',()=>life.abort(),{once:true});}

